import { redactSecrets } from "./secrets"

const RedactedPath = "<absolute path redacted>"
const groundTruthMarkers = /groundtruthlabel|adjudication_report|scoring/i

/** Removes host paths and research-only metadata from text generated by the harness or model. */
export const sanitizeSystemText = (text: string, secrets: readonly string[] = []): string => {
  const withoutSensitiveLines = text
    .split("\n")
    .filter((line) => !groundTruthMarkers.test(line))
    .join("\n")

  // Continuations allow spaces inside a path on the same line only; a newline always ends a path.
  const withoutWindowsPaths = withoutSensitiveLines
    .replace(/\b[A-Za-z]:[\\/][^\s"'<>|]+(?:[ \t]+[^\s"'<>|]*[\\/][^\s"'<>|]*)*/g, RedactedPath)
    .replace(/\\\\[^\\/\s]+(?:\\[^\\/\s]+)*(?:[ \t]+[^\\/\s]*\\[^\\/\s]*)*/g, RedactedPath)
  const withoutPosixPaths = withoutWindowsPaths.replace(
    /(^|[\s"'(])\/[^\s"'()<>{}\[\]]+(?:[ \t]+[^\s"'()<>{}\[\]]*\/[^\s"'()<>{}\[\]]*)*/gm,
    (_match, prefix: string) => prefix + RedactedPath,
  )

  return redactSecrets(withoutPosixPaths, secrets)
}

/** Redacts credentials while preserving snapshot source text and path-like comments exactly. */
export const sanitizeSourceContent = (text: string, secrets: readonly string[] = []): string =>
  redactSecrets(text, secrets)
